WITH car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,area FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao=2023 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2),b AS (SELECT c.id_imovel,c.area,SUM(op.valor_parcela_credito/n.n_imoveis) credito,SUM(op.area_financiada/n.n_imoveis) area_financiada,COUNT(DISTINCT op.id_referencia_bacen) operacoes FROM p JOIN n USING(id_referencia_bacen,numero_ordem) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao=2023 GROUP BY 1,2),x AS (SELECT * FROM b WHERE area<1 AND area_financiada>area) SELECT COUNT(*) imoveis,COUNT(DISTINCT operacoes) operacoes_distintas,SUM(credito) credito_alocado,SUM(area_financiada) area_financiada,SUM(area) area_car,SAFE_DIVIDE(SUM(area_financiada),SUM(area)) razao_agregada FROM x